def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent defections overall and in recent windows
    opp_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
    my_def = 0
    for m, o in history:
        if m == 'D':
            my_def += 1

    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Early game: cooperate, but immediately retaliate single defections
    if n < 4:
        return 'C'

    # Endgame: exploit known cooperativeness
    if n >= 100:
        if opp_def * 2 < n:
            return 'D'
        return 'C'
    if n >= 96:
        if opp_def * 3 < n:
            return 'D'
        if opp_def * 3 > n * 2:
            return 'D'
        return 'C'

    # Recent opponent defections (last 6)
    rd = 0
    start = n - 6 if n > 6 else 0
    for i in range(start, n):
        if history[i][1] == 'D':
            rd += 1

    # Recent opponent cooperation to detect nice opponents
    if rd == 0:
        return 'C'

    # If opponent is very defective overall, exploit-less: defect mostly
    if n >= 10 and opp_def * 2 > n:
        if rd >= 3:
            return 'D'
        if opp_last == 'D':
            return 'D'
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Tit-for-tat with light forgiveness for the middle game
    if opp_last == 'D':
        # Two consecutive defections -> retaliate firmly
        if n >= 2 and history[-2][1] == 'D':
            # If we have also been defecting a lot, try to reset
            if my_def >= 3 and rng.random() < 0.3:
                return 'C'
            return 'D'
        # Single defection -> retaliate, but sometimes forgive
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent cooperated last
    # Punish streaks of our own defection - return to cooperation
    if my_last == 'D' and my_def > opp_def + 2 and rng.random() < 0.7:
        return 'C'
    # If opponent has shown recent defections (rd >= 2), occasionally punish
    if rd >= 3 and rng.random() < 0.5:
        return 'D'
    if rd == 2 and opp_last == 'C' and rng.random() < 0.2:
        return 'D'
    return 'C'
